import {families,mappingRoles,labels,bytes} from './ingestion-catalog.js';

export const escapeImport=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const esc=escapeImport;
const paths={files:'M14 2H5a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V9zm0 0v7h7M7 13h10M7 17h7',review:'M9 3H4v18h16V8M9 3v5h11M8 13h5M8 17h4m5-2 2 2 4-5',match:'M3 6h6v5H3zm12 7h6v5h-6zM9 8h3v8h3M15 5h6M3 19h6',mapping:'M4 4h6v6H4zm10 0h6v6h-6zM4 14h6v6H4zm10 0h6v6h-6zM10 7h4M7 10v4m10-4v4m-7 3h4',upload:'M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5',check:'m5 12 4 4L19 6',arrow:'M4 12h16m-6-6 6 6-6 6',well:'M12 3v18M5 6h14M7 10h10m-9 5h8M4 21h16',logs:'M4 3h16v18H4zM9 3v18m6-18v18m-5-12 3 2-2 3 3 2-3 3',location:'M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Zm-4 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0',warning:'m12 3 10 18H2Zm0 6v5m0 3v1',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',inspect:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',rename:'m4 16 12-12 4 4L8 20H4Zm10-10 4 4',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',refresh:'M20 10a8 8 0 1 0 0 6M20 3v7h-7',chevron:'m9 5 7 7-7 7',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Zm-4 9 3 3 5-6',thumb:'M8 21H4V10h4Zm0-10 5-8c2 0 2 2 1 6h5c2 0 2 2 1 5l-2 7H8Z',clock:'M12 7v5l3 2m6-2a9 9 0 1 1-18 0 9 9 0 0 1 18 0',close:'m6 6 12 12M6 18 18 6'};
export const evidenceIcon=(name,className='')=>`<svg class="ie-icon ${className}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="${paths[name]||paths.files}"/></svg>`;
const typeName=id=>families.find(f=>f.id===id)?.name||id;
const input=(name,label,value='')=>`<label class="field">${esc(label)}<input name="${esc(name)}" value="${esc(value)}" autocomplete="off"></label>`;
const select=(name,label,values,value='')=>`<label class="field">${esc(label)}<select name="${esc(name)}"><option value="">Choose / unresolved</option>${values.map(v=>{const [id,title]=Array.isArray(v)?v:[v,v];return `<option value="${esc(id)}" ${String(value)===String(id)?'selected':''}>${esc(title)}</option>`;}).join('')}</select></label>`;
const pill=(text,tone='')=>`<span class="ie-pill ${tone}">${esc(text)}</span>`;
const panel=(title,body,icon='files',extra='')=>`<section class="ie-panel ${extra}"><header class="ie-panel-heading">${evidenceIcon(icon)}<h4>${esc(title)}</h4></header>${body}</section>`;
const isLog=asset=>['logs','arrays'].includes(asset.family);
const issueList=asset=>[...(asset.preview?.issues||[]),...(asset.evidence?.issues||[]),...(asset.batchIssues||[])];
const columnsSelected=a=>(a.preview?.columns||[]).filter(c=>c.id==='column-'+a.options.mapping?.index||a.options.curves?.[c.id]?.selected!==false);

export function importIllustration(kind='files'){
 return `<svg class="ie-illustration" viewBox="0 0 300 174" fill="none" aria-hidden="true" focusable="false"><path d="M23 138h253M41 28v112m212-112v112" stroke="#d9e7e3" stroke-dasharray="3 5"/><rect x="75" y="21" width="98" height="128" rx="7" fill="white" stroke="#a4c6bc"/><path d="M141 21v28h32M89 67h58m-58 13h40m-40 13h58m-58 13h35m-35 13h47" stroke="#9bb8b0" stroke-width="2"/><rect x="170" y="77" width="78" height="72" rx="7" fill="#e6f3ef" stroke="#a4c6bc"/><path d="M188 111h42m-21-21v46M193 98h32m-27 24h22" stroke="#087c73" stroke-width="2"/><path d="m37 84 12 12 20-28" stroke="#087c73" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><circle cx="237" cy="41" r="14" fill="#087c73"/><path d="M237 34v14m-7-7h14" stroke="white" stroke-width="2"/>${kind==='match'?'<path d="M153 102h34m-7-7 7 7-7 7" stroke="#087c73" stroke-width="2"/>':''}</svg>`;
}

export function importNavigation(step,assets,project){
 const stages=[['Files','Choose your evidence','files'],['Review','Look inside the originals','review'],['Match','Connect files to wells','match'],['Mapping','Confirm fields and units','mapping'],['Import','Bring it into your project','upload']];
 return `<aside class="ie-rail"><div class="ie-rail-label">IMPORT WORKFLOW</div><nav aria-label="Import progress">${stages.map(([title,detail,icon],i)=>`<div class="ie-stage ${step===i?'is-current':step>i?'is-complete':''}" ${step===i?'aria-current="step"':''}><span class="ie-stage-icon">${evidenceIcon(step>i?'check':icon)}</span><span><strong>${i+1}. ${title}</strong><small>${detail}</small></span></div>`).join('')}</nav><div class="ie-destination">${evidenceIcon('shield')}<div><strong>${esc(project.name||'Current project')}</strong><small>${project.storage==='cloud'?'Private Cloud storage':project.storage==='local'?'Local project folder':'Portable project'}</small><span>${assets.length} ${assets.length===1?'source':'sources'}${assets.length?' / '+bytes(assets.reduce((n,a)=>n+a.file.size,0)):''}</span></div></div></aside>`;
}

function assetList(s){return `<nav class="ie-assets" aria-label="Selected source files">${s.assets.map(a=>`<button type="button" data-asset="${a.id}" ${a===s.current?'aria-current="true"':''}><span class="ie-file-symbol">${evidenceIcon(isLog(a)?'logs':a.family==='well_headers'?'well':'files')}</span><span><strong>${esc(a.file.name)}</strong><small>${esc(a.retainOnly?'Retained ZIP original':typeName(a.family)||'Choose type')} / ${bytes(a.file.size)}</small></span>${a===s.current?evidenceIcon('check'):''}</button>`).join('')}</nav>`;}

function headerChoice(s){
 const logs=s.assets.filter(isLog),headers=s.assets.filter(a=>a.family==='well_headers');
 if(headers.length)return panel('Well headers included',`<p>Your header files define the well records. Match your logs to these wells in the next steps.</p>${pill(headers.length+' header '+(headers.length===1?'file':'files'),'is-good')}`,'well');
 return `<section class="ie-header-choice ${s.deriveHeaders?'is-selected':''}"><div class="ie-choice-graphic">${evidenceIcon('logs')}${evidenceIcon('arrow')}${evidenceIcon('well')}</div><label><input id="wi-build-headers" type="checkbox" ${s.deriveHeaders?'checked':''} ${s.busy?'disabled':''}><span><strong>Create well headers from log files</strong><small>Importing without a header file? Use the well identifiers, locations, elevations and depths available in your logs.</small></span></label><p>${logs.length?s.deriveHeaders?'Available metadata will be shown for review. Missing values stay unresolved.':'Tick to create new well records, or match your logs to existing wells.':'Add log files to use this option. You can also upload a header file.'}</p></section>`;
}

function sourcePreview(asset){
 const d=asset?.preview;
 if(!d)return `<div class="ie-empty-inspection">${evidenceIcon('inspect')}<strong>${asset?.retainOnly?'ZIP original retained':asset?'Native inspection required':'No source selected'}</strong><p>${esc(asset?.notice||'Choose a source to inspect its contents.')}</p></div>`;
 return `<div class="ie-table-heading"><strong>Source records</strong><span>${d.columns.length} columns / showing ${Math.min(30,d.preview.length)} records</span></div><div class="table-wrap wi-preview ie-source-table"><table><thead><tr><th>Row</th>${d.columns.map(c=>`<th>${esc(c.mnemonic)}<small>${esc(c.unit||'Unit not supplied')}</small></th>`).join('')}</tr></thead><tbody>${d.preview.slice(0,30).map((row,i)=>`<tr><td>${i+1}</td>${row.map(v=>`<td>${esc(typeof v==='object'&&v!==null?JSON.stringify(v):v??'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
}

export function groupedImportIssues(issues=[]){
 const groups=new Map();for(const issue of issues){const key=issue.code+'|'+issue.severity;let group=groups.get(key);if(!group){group={...issue,sources:new Set(),count:0};groups.set(key,group);}group.count++;if(issue.source)group.sources.add(issue.source);}
 if(!groups.size)return `<div class="ie-clear">${evidenceIcon('check')}No outstanding import warnings.</div>`;
 return `<div class="ie-issues">${[...groups.values()].map(issue=>`<div class="ie-issue ${issue.severity==='blocking'?'is-blocking':''}">${evidenceIcon('warning')}<div><strong>${issue.severity==='blocking'?'Resolve before import':'Review note'}${issue.count>1?' / '+issue.count+' occurrences':''}</strong><p>${esc(issue.message)}</p>${issue.sources.size?`<small>${[...issue.sources].map(esc).join(' · ')}</small>`:''}</div></div>`).join('')}</div>`;
}

function archiveInventory(s){
 const roots=s.assets.filter(a=>a.archiveRoot);if(!roots.length)return '';
 return `<div class="ie-archive-review"><label class="field">ZIP password, if needed<input id="wi-zip-password" type="password" autocomplete="off" placeholder="Used only to open entries in this browser"></label>${roots.map(root=>{const entries=[...s.assets,...s.excludedAssets].filter(a=>a.archive?.rootId===root.id),notes=root.archiveNotes||[],page=root.notePage||0;return `<details class="ie-details" open><summary>${evidenceIcon('files')}${esc(root.file.name)} / ${entries.length} readable entries</summary><p class="ie-inline-note">The ZIP original is retained. Review detected types below; use the source selector to correct a type or the Match step to change a well association.</p><div class="table-wrap ie-archive-table"><table><thead><tr><th>Include</th><th>Archive entry</th><th>Detected type</th><th>Association</th></tr></thead><tbody>${entries.map(a=>`<tr><td><input type="checkbox" data-archive-include="${a.id}" ${s.assets.some(source=>source.id===a.id)?'checked':''} aria-label="Include ${esc(a.archive.path)}"></td><td><button type="button" data-asset="${a.id}" ${s.excludedAssets.some(source=>source.id===a.id)?'disabled':''}>${esc(a.archive.path)}</button></td><td>${esc(a.family?typeName(a.family):'Choose a type')}</td><td>${esc(a.relatedTo?'Suggested from log / '+(s.assets.find(log=>log.id===a.relatedTo)?.wellName||s.assets.find(log=>log.id===a.relatedTo)?.file.name||'review'):a.archiveAssociationNote||'Confirm in Match')}</td></tr>`).join('')}</tbody></table></div>${notes.length?`<div class="ie-archive-notes"><strong>${notes.length} excluded or unreadable entries / review notes</strong>${notes.slice(page*50,(page+1)*50).map(note=>`<p><strong>${esc(note.path)}</strong><span>${esc(note.message)}</span></p>`).join('')}${notes.length>50?`<div class="ie-pagination"><button type="button" data-archive-root="${root.id}" data-archive-notes-page="${page-1}" ${page===0?'disabled':''}>Previous</button><span>${page*50+1}–${Math.min(notes.length,(page+1)*50)} of ${notes.length}</span><button type="button" data-archive-root="${root.id}" data-archive-notes-page="${page+1}" ${(page+1)*50>=notes.length?'disabled':''}>Next</button></div>`:''}</div>`:''}<button type="button" data-retry-archive="${root.id}">Unlock / retry this ZIP</button></details>`;}).join('')}</div>`;
}

function relatedSurveyChoice(s){
 const selected=s.current,parent=isLog(selected||{})?selected:s.assets.find(a=>a.id===selected?.relatedTo);if(!parent)return '';
 const surveys=s.assets.filter(a=>a.relatedTo===parent.id&&a.family==='deviation');
 return `<section class="ie-related-survey"><div>${evidenceIcon('well')}<span><strong>Deviation for ${esc(parent.wellName||parent.file.name)}</strong><small>Add this well’s survey now. Logs and deviation will be reviewed and imported together.</small></span></div><button type="button" id="wi-add-deviation" data-log-asset="${parent.id}">${evidenceIcon('upload')}Add deviation for this well</button><input id="wi-deviation-files" type="file" multiple hidden>${surveys.length?`<ul>${surveys.map(a=>`<li>${evidenceIcon('check')}${esc(a.file.name)}</li>`).join('')}</ul>`:'<p>Optional / MD–inclination–azimuth or supported coordinate surveys.</p>'}</section>`;
}

function filesStep(s){
 const a=s.current;
 return `<div class="ie-stage-heading"><span class="ie-eyebrow">YOUR PROJECT STARTS WITH EVIDENCE</span><h3>Bring your well data together.</h3><p>Add logs, headers, ZIP bundles and supporting files. We’ll identify their contents and help you connect them.</p></div><div class="ie-two-column"><div><label class="ie-drop" id="wi-drop-zone">${importIllustration()}<strong>Drop your files here</strong><span>or choose files from your device</span><span class="ie-choose-button">${evidenceIcon('upload')}Choose files</span><input id="wi-files" type="file" multiple ${s.busy?'disabled':''}></label><div class="ie-format-strip">${['LAS / DLIS / LIS','ZIP bundles','Headers & tables','Surveys & tops'].map(label=>`<span>${esc(label)}</span>`).join('')}</div>${s.project.storage==='local'&&window.showOpenFilePicker?'<button type="button" id="wi-linked" class="ie-link-button">Link originals from this device</button>':''}</div><div>${headerChoice(s)}${relatedSurveyChoice(s)}${panel('One well, connected evidence','<p>Logs, deviation surveys, tops and checkshots stay attached to their owning well. Supporting files are optional. You can correct every detected file type.</p>','match')}</div></div>${archiveInventory(s)}${s.assets.length?`<div class="ie-section-heading"><h4>Selected sources</h4>${pill(s.assets.length+' files')}</div>${assetList(s)}${a?`<div class="ie-source-settings">${a.retainOnly?pill('ZIP original / retained without parsing'):select('family','Selected source type',s.available.map(f=>[f.id,f.name]),a.family)}<button type="button" id="wi-remove" class="ie-danger-link">${a.archiveRoot?'Remove archive and its entries':'Remove selected file'}</button></div>`:''}`:''}`;
}

function reviewStep(s){
 const a=s.current,rows=a?.preview?.reviewRows||a?.preview?.preview||[],page=a?.headerPage||0;
 return `<div class="ie-stage-heading"><span class="ie-eyebrow">A CLOSER LOOK</span><h3>Know what you’re importing.</h3><p>Review the original records and any points that need attention before connecting your wells.</p></div>${assetList(s)}${a?`<div class="ie-source-toolbar"><div>${evidenceIcon('files')}<strong>${esc(a.file.name)}</strong>${pill(typeName(a.family))}</div><div><button type="button" id="wi-text">${evidenceIcon('inspect')}View full source</button><button type="button" id="wi-download">${evidenceIcon('download')}Original</button></div></div>${sourcePreview(a)}${issueList(a).length?`<details class="ie-details" open><summary>Review notes ${pill(issueList(a).length)}</summary>${groupedImportIssues(issueList(a))}</details>`:'<p class="ie-inline-note">Source records are preserved as uploaded. You can adjust their interpretation in Mapping.</p>'}${a.family==='well_headers'&&a.preview?`<details class="ie-details" open><summary>Header rows / duplicate decisions</summary><p>Keep records separately, skip a registration, or choose the well to merge into.</p><div class="ie-header-rows">${rows.slice(page*50,(page+1)*50).map((row,index)=>{const i=page*50+index;return select('header:'+i,'Row '+(i+1)+' / '+(row[Number(a.options.mapping.well)]??''),[['keep','Keep as independent well'],['skip','Skip this registration'],...s.candidates.map(w=>[w.id,'Merge into '+(w.name||w.id)+' / '+w.id.slice(-8)])],a.options.headerActions?.[i]?.action==='skip'?'skip':a.options.headerActions?.[i]?.well||'keep').replace('<select ','<select data-header-action="'+i+'" ');}).join('')}</div>${rows.length>50?`<div class="ie-pagination"><button type="button" data-header-page="${page-1}" ${page===0?'disabled':''}>Previous</button><span>Rows ${page*50+1}–${Math.min((page+1)*50,rows.length)} of ${rows.length}</span><button type="button" data-header-page="${page+1}" ${(page+1)*50>=rows.length?'disabled':''}>Next</button></div>`:''}</details>`:''}`:''}`;
}

function matchStep(s){
 return `<div class="ie-stage-heading"><span class="ie-eyebrow">EVERY FILE HAS A HOME</span><h3>Connect your files to wells.</h3><p>Unique matches are filled in for you. Confirm the destination for each source and resolve any ambiguity.</p></div><div class="ie-rules"><div class="ie-rule-fields">${select('matchField','Match wells using',[['name','Well name'],['uwi','UWI / API']],s.matchField)}${select('identitySource','Log identity comes from',[['header','Log header'],['file','Filename']],s.identitySource)}<label class="ie-check"><input name="exact" type="checkbox" ${s.exact?'checked':''}>Exact matching</label><button type="button" id="wi-rematch">Apply matching rule</button></div></div>${s.assets.filter(a=>!['well_headers','documents','seismic'].includes(a.family)).map(a=>`<section class="ie-association"><div class="ie-association-source">${evidenceIcon(isLog(a)?'logs':'files')}<span><strong>${esc(a.file.name)}</strong><small>Detected identity: ${esc(a.identity||'Not available')}</small></span></div>${evidenceIcon('arrow','ie-association-arrow')}<div>${Object.keys(a.bindings).length?`<details open><summary>${Object.keys(a.bindings).length} row-level well associations</summary>${Object.keys(a.bindings).map(raw=>select('binding:'+a.id+':'+raw,raw,s.wellOptions(a,raw),a.bindings[raw])).join('')}</details>`:select('well:'+a.id,'Destination well',s.wellOptions(a),a.options.well)}${a.relatedTo?`<p class="ie-inline-note">Added with ${esc(s.assets.find(log=>log.id===a.relatedTo)?.file.name||'its well log')}. ${a.manualWell?'Destination selected separately.':'Destination follows the log’s well.'}</p>`:''}${a.relatedConflict?`<p class="ie-field-warning">${esc(a.relatedConflict)}</p><label class="ie-check"><input name="confirm-related:${a.id}" type="checkbox" ${a.confirmRelated?'checked':''}>Use the selected well despite this difference</label>`:''}${isLog(a)&&!s.deriveHeaders&&!a.options.well?'<p class="ie-field-warning">Choose an existing well, add headers, or enable header creation below.</p>':''}</div></section>`).join('')}<div class="ie-match-footer">${headerChoice(s)}</div>`;
}

function mappingStep(s){
 const a=s.current;if(a?.retainOnly)return `<div class="ie-stage-heading"><span class="ie-eyebrow">ORIGINAL ARCHIVE</span><h3>Map the files inside your ZIP.</h3><p>The ZIP itself is retained unchanged. Select an extracted source below to review its fields, units and references.</p></div>${assetList(s)}<div class="ie-empty-inspection">${evidenceIcon('shield')}<strong>Original archive retained</strong><p>Its selected entries are mapped and imported independently.</p></div>`;if(!a)return '';
 const columns=a.preview?.columns||[],o=a.options,r=o.references||{},roles=[...new Set(mappingRoles[a.family]||[])];
 const sourceValue=role=>{const index=o.mapping[role];if(index===''||index===undefined)return 'Not mapped';const value=a.preview?.preview?.find(row=>row[Number(index)]!==null)?.[Number(index)];return value===undefined?'No value in preview':String(value);};
 const references=`${['seismic','surfaces','models'].includes(a.family)?select('ref:domain','Vertical domain',['Time','Depth'],r.domain):''}${select('ref:depthReference','Depth reference',['MD','TVD','TVDSS'],r.depthReference)}${select('ref:depthUnit','Depth units',['m','ft'],r.depthUnit)}${input('ref:crs','Coordinate reference / CRS',r.crs)}${select('ref:coordinateOrder','Coordinate order',['X / Y','Longitude / latitude','Latitude / longitude'],r.coordinateOrder)}${input('ref:verticalDatum','Elevation / depth datum',r.verticalDatum)}${select('ref:elevationUnit','Well elevation unit',['m','ft'],r.elevationUnit)}${a.family==='deviation'?select('surveyMethod','Survey representation',[['angles','MD / inclination / azimuth'],['offsets','DX / DY / TVD'],['xy_tvd','X / Y / TVD'],['coordinates','X / Y / Z']],o.surveyMethod)+select('ref:verticalMeaning','Z convention',['Depth positive down','Elevation positive up'],r.verticalMeaning)+select('ref:offsetUnit','Horizontal offset unit',['m','ft'],r.offsetUnit)+select('ref:northReference','Azimuth north',['Grid north','True north','Magnetic north'],r.northReference)+select('ref:angleUnit','Angle unit',['degrees','radians'],r.angleUnit)+input('northCorrection','True-to-grid correction (degrees)',r.northCorrection)+input('declination','Magnetic declination (degrees)',r.declination):''}${a.family==='checkshots'?select('ref:timeConvention','Time convention',['One-way time','Two-way time'],r.timeConvention)+select('ref:timeUnit','Time units',['ms','s'],r.timeUnit)+input('ref:timeDatum','Time datum',r.timeDatum)+select('ref:depthSign','Depth sign',[['1','Positive source depth'],['-1','Negative source depth']],r.depthSign||'1')+select('ref:timeSign','Time sign',[['1','Positive source time'],['-1','Negative source time']],r.timeSign||'1'):''}`;
 return `<div class="ie-stage-heading"><span class="ie-eyebrow">SOURCE VALUES, CLEAR MEANING</span><h3>Make the data speak your language.</h3><p>Detected mappings are editable. Confirm what each field means and which curves to bring into the project.</p></div>${assetList(s)}<div class="ie-mapping-heading"><h4>Field mapping</h4><button type="button" id="wi-apply">${evidenceIcon('mapping')}Apply to compatible files</button></div><div class="table-wrap ie-mapping-table"><table><thead><tr><th>Use as</th><th>Source column</th><th>Example from source</th></tr></thead><tbody>${roles.map(role=>`<tr><th>${esc(labels[role]||role)}</th><td>${select('map:'+role,labels[role]||role,columns.map((c,i)=>[String(i),c.mnemonic+(c.unit?' / '+c.unit:'')]),o.mapping[role]??'')}</td><td class="ie-source-value">${esc(sourceValue(role))}</td></tr>`).join('')}</tbody></table></div><details open class="ie-details"><summary>${evidenceIcon('location')}Units and scientific references</summary><div class="form-grid">${references}</div><p class="ie-inline-note">Unconfirmed coordinates remain off the map. Original measurements stay unchanged.</p></details>${isLog(a)?`<details open class="ie-details"><summary>${evidenceIcon('logs')}Curves to import ${pill(columnsSelected(a).length+' selected')}</summary><div class="ie-curve-controls"><span>Import selection is separate from display visibility.</span><button type="button" data-load="all">Select all</button><button type="button" data-load="none">Clear selection</button></div><div class="table-wrap ie-curve-table"><table><thead><tr><th>Load</th><th>Original curve</th><th>Curve type</th><th>Confirmed unit</th></tr></thead><tbody>${columns.map(c=>`<tr><td><input type="checkbox" name="load:${esc(c.id)}" ${String(o.mapping.index)===c.id.split('-')[1]?'checked disabled':o.curves[c.id]?.selected!==false?'checked':''} aria-label="Import ${esc(c.mnemonic)}"></td><th>${esc(c.mnemonic)}<small>${esc(c.unit||'Unit not supplied')}${String(o.mapping.index)===c.id.split('-')[1]?' / required index':''}</small></th><td>${select('type:'+c.id,'Curve type',[['gamma','Gamma ray'],['resistivity','Resistivity'],['porosity','Porosity'],['density','Density'],['neutron','Neutron'],['sonic','Sonic'],['caliper','Caliper'],['permeability','Permeability'],['facies','Facies']],o.curves[c.id]?.propertyType)}</td><td>${input('unit:'+c.id.split('-')[1],'Unit',o.units[c.id.split('-')[1]]||'')}</td></tr>`).join('')}</tbody></table></div></details>`:''}<details class="ie-details"><summary>Source layout and advanced options</summary><div class="form-grid">${input('headerRow','Header row (1-based)',o.headerRow||1)}${select('delimiter','Delimiter',[['','Auto'],[',','Comma'],['\t','Tab'],[';','Semicolon'],['whitespace','Whitespace']],o.delimiter)}${input('null','Undefined value',o.null)}${input('encoding','Encoding',o.encoding||'utf-8')}${input('sheet','Worksheet',o.sheet)}${input('widths','Fixed-width sizes',(o.widths||[]).join(','))}${input('jsonPath','JSON record-array path',o.jsonPath)}${input('hdfPaths','HDF5 dataset paths',(o.hdfPaths||[]).join(','))}${input('frames','Native frame names',(o.frames||[]).join(','))}${select('endian','Seismic byte order',['big','little'],o.endian||'big')}${['inline','crossline','x','y','scalar'].map(key=>input('byte:'+key,'Trace header byte / '+key,o.headerBytes?.[key]||({inline:189,crossline:193,x:181,y:185,scalar:71})[key])).join('')}${input('surfaceFormat','Surface dialect',o.surfaceFormat)}<label class="ie-check"><input type="checkbox" name="noHeader" ${o.noHeader?'checked':''}>No header row</label></div><button type="button" id="wi-repreview">Re-read with this layout</button></details><details class="ie-details"><summary>Source preview</summary>${sourcePreview(a)}</details>`;
}

function readableSummary(a,s){
 if(a.retainOnly)return `<article class="ie-confirm-file"><div class="ie-confirm-file-title">${evidenceIcon('files')}<div><strong>${esc(a.file.name)}</strong><small>Original ZIP / ${bytes(a.file.size)}</small></div>${pill('Retained original')}</div><p class="ie-inline-note">Selected entries are imported individually with their archive paths preserved.</p></article>`;
 const r=a.options.references||{},entries=Object.entries(a.options.mapping||{}).filter(([,value])=>value!==''&&value!==undefined),well=s.candidates.find(w=>w.id===a.options.well),associations=Object.entries(a.bindings||{});
 return `<article class="ie-confirm-file"><div class="ie-confirm-file-title">${evidenceIcon(isLog(a)?'logs':'files')}<div><strong>${esc(a.file.name)}</strong><small>${esc(typeName(a.family))} / ${bytes(a.file.size)}</small></div>${pill(associations.length?associations.length+' wells':well?.name||a.wellName||'Well headers')}</div><div class="ie-confirm-tags">${r.depthReference?pill(r.depthReference):''}${r.depthUnit?pill(r.depthUnit):''}${r.crs?pill(r.crs):''}${isLog(a)?pill(columnsSelected(a).length+' selected columns'):''}</div><details class="ie-file-review"><summary>Review mapping and associations</summary><dl>${entries.map(([role,index])=>`<dt>${esc(labels[role]||role)}</dt><dd>${esc(a.preview?.columns?.[Number(index)]?.mnemonic||'Column '+(Number(index)+1))}</dd>`).join('')}${associations.map(([raw,id])=>`<dt>${esc(raw)}</dt><dd>${esc(s.candidates.find(w=>w.id===id)?.name||'Association needs review')}</dd>`).join('')}</dl>${r.verticalDatum?`<p>Depth / elevation datum: ${esc(r.verticalDatum)}</p>`:''}${r.timeConvention?`<p>${esc(r.timeConvention)} / ${esc(r.timeUnit||'time unit unresolved')}</p>`:''}</details></article>`;
}

export function renderImportProgress(assets){
 return `<section class="ie-progress" id="wi-progress" aria-busy="true"><div class="ie-progress-title"><span class="ie-progress-symbol">${evidenceIcon('upload')}</span><div><h4 id="wi-progress-label">Preparing your import</h4><p id="wi-progress-message" role="status" aria-live="polite">Starting…</p></div><strong id="wi-progress-percent"></strong></div><p id="wi-progress-meta" class="ie-progress-meta"></p><progress id="wi-progress-bar" max="100" aria-label="Current import stage"></progress><div class="ie-progress-stages">${[['reading','Read'],['hashing','Check duplicates'],['uploading','Transfer'],['inspecting','Inspect'],['activating','Finish']].map(([phase,title])=>`<span data-import-phase="${phase}">${evidenceIcon(phase==='activating'?'check':phase==='inspecting'?'review':phase==='hashing'?'shield':phase==='reading'?'files':'upload')}<small>${title}</small></span>`).join('')}</div><div class="ie-file-progress-list">${assets.map(a=>`<div data-import-progress-file="${a.id}"><span>${evidenceIcon(isLog(a)?'logs':'files')}<strong>${esc(a.file.name)}</strong></span><small>Waiting</small></div>`).join('')}</div></section>`;
}

function confirmStep(s){
 if(s.busy)return `<div class="ie-stage-heading"><span class="ie-eyebrow">BRINGING YOUR EVIDENCE IN</span><h3>Your import is in progress.</h3><p>Keep this window open while originals are transferred and inspected.</p></div>${renderImportProgress(s.assets)}`;
 return `<div class="ie-stage-heading"><span class="ie-eyebrow">READY WHEN YOU ARE</span><h3>One last look, then import.</h3><p>Confirm the destination, well associations and settings for your selected evidence.</p></div><div class="ie-confirm-overview"><div>${evidenceIcon('shield')}<span>Destination<strong>${esc(s.project.name||'Current project')}</strong><small>${s.project.storage==='cloud'?'Private Cloud storage':s.project.storage==='local'?'Local project folder':'Portable project'}</small></span></div><div><strong>${s.assets.length}</strong><span>source files<small>${bytes(s.assets.reduce((n,a)=>n+a.file.size,0))} in total</small></span></div><div>${evidenceIcon('well')}<span>Well headers<strong>${s.deriveHeaders?'Create from log metadata':s.assets.some(a=>a.family==='well_headers')?'Use uploaded headers':'Use existing wells'}</strong></span></div></div><div class="ie-confirm-files">${s.assets.map(a=>readableSummary(a,s)).join('')}</div>${s.assets.filter(a=>a.archiveRoot&&a.archiveNotes?.some(n=>n.code!=='zip_metadata')).map(a=>`<details class="ie-details"><summary>${evidenceIcon('warning')}ZIP review / ${esc(a.file.name)}</summary><div class="ie-archive-notes"><p>Some entries were excluded or could not be read. Their original bytes remain in the retained ZIP. Return to Files for the complete inventory.</p>${a.archiveNotes.filter(n=>n.code!=='zip_metadata').slice(0,50).map(n=>`<p><strong>${esc(n.path)}</strong><span>${esc(n.message)}</span></p>`).join('')}</div></details>`).join('')}<label class="ie-authority">${evidenceIcon('shield')}<input id="wi-authority" type="checkbox" ${s.reviewedWarnings?'checked':''}><span><strong>Ready to import into this project</strong><small>I have authority to use these files and have reviewed the destination, well associations and remaining warnings.</small></span></label>${s.record?`<div class="ie-pending-result">${groupedImportIssues(s.record.issues)}<button type="button" id="wi-review-result">Review inspection results</button></div>`:''}`;
}

export function importStep(s){return [filesStep,reviewStep,matchStep,mappingStep,confirmStep][s.step](s);}

export function importCompletion(s){
 const imported=s.record.committedAt,issues=s.record.issues||[],datasets=s.record.datasets||[],included=datasets.filter(d=>!imported||d.active!==false),wellCount=new Set(included.flatMap(d=>[d.well,...(d.wellRecords||[]).map(w=>w.id)]).filter(Boolean)).size;
 return `<div class="ie-completion ${imported?'is-success':'needs-review'}"><div class="ie-completion-art">${evidenceIcon(imported?'thumb':'review')}</div>${pill(imported?'IMPORT COMPLETE':'INSPECTION COMPLETE',imported?'is-good':'is-amber')}<h3 tabindex="-1" id="wi-completion-title">${imported?'Your evidence is ready.':'A few details need your review.'}</h3><p>${imported?'Your selected data has been imported into '+esc(s.project.name||'this project')+'. Original measurements are preserved.':'Your originals are retained. Review the inspection differences before activating the data.'}</p><div class="ie-completion-counts"><span><strong>${s.assets.length}</strong>source files</span><span><strong>${included.length}</strong>datasets</span><span><strong>${wellCount}</strong>well associations</span></div><details class="ie-completion-review" ${!imported?'open':''}><summary>${evidenceIcon('inspect')}Review imported data${evidenceIcon('chevron')}<span>${issues.length?issues.length+' review notes':'Import details'}</span></summary><div>${datasets.map(d=>`<div class="ie-completed-dataset">${evidenceIcon('logs')}<span><strong>${esc(d.name)}</strong><small>${Number(d.rowCount||0).toLocaleString()} records / ${d.columns?.length||0} columns</small></span>${pill(d.active?'Imported':'Retained')}</div>`).join('')}${groupedImportIssues(issues)}<p class="ie-inline-note">Import completion is separate from scientific approval. Unconfirmed units and location references still need review.</p></div></details><details class="ie-timings"><summary>${evidenceIcon('clock')}Import timings</summary><dl>${Object.entries(s.record.timings||{}).filter(([,value])=>Number.isFinite(value)).map(([key,value])=>`<dt>${esc(({totalMs:'Total time',hashMs:'Duplicate checking',transferMs:'Transfer',inspectMs:'Inspection',inspectionWaitMs:'Inspection and queue',parseAndRetentionMs:'Read and retain'})[key]||key)}</dt><dd>${(value/1000).toFixed(1)} s</dd>`).join('')}</dl></details><div class="ie-completion-actions">${imported&&included.some(d=>d.family==='logs')?'<button type="button" id="wi-view-logs" class="primary">Open log viewer</button>':''}${imported&&wellCount?'<button type="button" id="wi-view-map">Open map / review locations</button>':''}${imported?'<button type="button" id="wi-done" class="primary">Done</button>':'<button type="button" id="wi-review-result" class="primary">Review inspection results</button>'}<button type="button" id="wi-view-data">Open project data</button></div></div>`;
}

export function updateImportProgress(root,state){
 if(!root)return;
 const phaseLabels={reading:'Reading source files',hashing:'Checking for retained originals',uploading:'Transferring originals',retaining:'Saving originals on this device',inspecting:'Inspecting the evidence',parsing:'Reading and parsing',activating:'Activating reviewed data'};
 const percent=Number.isFinite(state.percent)?Math.max(0,Math.min(100,state.percent)):null,bar=root.querySelector('#wi-progress-bar');
 const setText=(selector,value)=>{const node=root.querySelector(selector);if(node.textContent!==value)node.textContent=value;};setText('#wi-progress-label',state.label||phaseLabels[state.phase]||'Preparing your import');setText('#wi-progress-message',state.message||'');root.querySelector('#wi-progress-percent').textContent=percent===null?'':Math.floor(percent)+'%';root.querySelector('#wi-progress-meta').textContent=state.meta||'';
 if(percent===null)bar.removeAttribute('value');else bar.value=percent;
 const order=['reading','hashing','uploading','inspecting','activating'],phase=state.phase==='retaining'?'uploading':state.phase==='parsing'?'inspecting':state.phase;
 root.querySelectorAll('[data-import-phase]').forEach(el=>{el.classList.toggle('is-current',el.dataset.importPhase===phase);el.classList.toggle('is-complete',order.indexOf(el.dataset.importPhase)<order.indexOf(phase));});
 for(const [id,file]of Object.entries(state.files||{})){const el=root.querySelector(`[data-import-progress-file="${id}"]`);if(!el)continue;el.querySelector('small').textContent=file.message||'';el.classList.toggle('is-complete',file.percent===100);}
}
